-- Human-run only. Agent does not apply this against any database.
-- Bed linen listing template + column seed.
-- Prerequisites:
--   1) Run 001_category_intelligence_and_listing.sql
--   2) Ensure category_marketplace exists for the Bed Linen × Amazon pair
--   3) Upload BED_LINEN_SET.xlsm via PUT /api/catalog/listing-template (or set gcs key below)
-- Replace :category_marketplace_id and gcs_object_key placeholders before running.

BEGIN;

-- Insert or reuse listing_template for the target category_marketplace.
-- Example: set cm_id from your DB, then run the rest.
-- \set cm_id 1

WITH upsert AS (
  VALUES (
    :cm_id,  -- << set category_marketplace.id
    'listing-templates/marketplaces/<marketplace_ext>/categories/<category_ext>/template.xlsx',
    '{"filename": "BED_LINEN_SET.xlsm", "sheet_name": "Template", "header_label_row": 4, "machine_key_row": 5, "data_start_row": 7}'::jsonb
  )
  ON CONFLICT (category_marketplace_id) DO UPDATE
    SET metadata = EXCLUDED.metadata,
        updated_at = now()
  RETURNING id
)
SELECT id AS listing_template_id FROM upsert;

-- Delete existing columns for this template then re-insert (idempotent re-seed).
-- Set :lt_id to the listing_template.id from above.
DELETE FROM listing_template_column WHERE listing_template_id = :lt_id;


COMMIT;

-- Seeded 272 columns from BED_LINEN_SET (1).xlsm